/**
 * Mock-mode data, generated by `npm run mock:data -w @surety/web`, which runs a
 * scenario on MockChain (the shared copy of the contract rules). Timestamps are
 * shifted so the newest event is "just now".
 */
import type { AgentView, JobView, Verdict } from '../shared/types';
import raw from './fixture.json';

const shift = Date.now() - raw.now_ms;
const t = (ms: number) => ms + shift;

export const MOCK_AGENTS: AgentView[] = (raw.agents as AgentView[]).map((a) => ({
  ...a,
  registered_ms: t(a.registered_ms),
}));

export const MOCK_JOBS: JobView[] = (raw.jobs as JobView[]).map((j) => ({
  ...j,
  posted_ms: t(j.posted_ms),
  deadline_ms: t(j.deadline_ms),
  verdict: j.verdict && { ...j.verdict, judged_ms: t(j.verdict.judged_ms), appeal_deadline_ms: t(j.verdict.appeal_deadline_ms) },
  settlement: j.settlement && { ...j.settlement, settled_ms: t(j.settlement.settled_ms) },
}));

export const MOCK_RECEIPTS: Record<number, Verdict> = Object.fromEntries(
  Object.entries(raw.verdicts as Record<string, Verdict>).map(([id, v]) => [Number(id), { ...v, judged_at_ms: t(v.judged_at_ms) }]),
);
